const body = $input.first().json.body || $input.first().json;
const reviewId = body.reviewId || Date.now();
const rating = body.rating || 5;
const title = body.title || '';
const reviewBody = body.body || '';
const productTitle = body.productTitle || 'Our product';
const reviewerName = body.reviewerName || 'Customer';
const platform = body.platform || 'shopify';

return [{
  json: {
    reviewId,
    rating,
    title,
    body: reviewBody,
    productTitle,
    reviewerName,
    platform,
    chatInput: 'Product: ' + productTitle + '\nRating: ' + rating + '/5\nReviewer: ' + reviewerName + '\nPlatform: ' + platform + '\nTitle: ' + title + '\nBody: ' + reviewBody
  }
}];

const review = $('Parse Input').first().json;
const reply = ($input.first().json.output || $input.first().json.text || '').trim();
const rating = Number(review.rating);
const status = rating <= 3 ? 'needs_approval' : 'auto_replied';

return [{
  json: {
    status,
    reviewId: review.reviewId,
    rating,
    productTitle: review.productTitle,
    reviewerName: review.reviewerName,
    platform: review.platform,
    generatedReply: reply,
    originalReview: review.chatInput
  }
}];

